head.script:
scwin.screenId = "jldfil40209";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40209.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_ApplyJoin_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_ApplyJoin_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_ApplyJoin_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.applyJoin()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40209.btn_ApplyJoin_onclick' }); }
};

/**
 * @event
 * @name scwin.btn_GoURL_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_GoURL_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_GoURL_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.goURL('cancel')
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40209.btn_GoURL_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_ApplyJoin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_ApplyJoin = async function () {
    const sbmOptions = {
        id: "tx_fn_ApplyJoin",
        method: "post",
        action: "/outer/benfcertApct.do",
        ref: "dma_ApplyJoinReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40209.tx_fn_ApplyJoin" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.goURL
 * @author Inswave
 * @date 2026. 09. 29
 * @param _target
 * @returns
 * @hidden N
*/
scwin.goURL = function (_target) {
    /* sdd-asis-lifecycle:begin fn_GoURL — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let linkUrl;
    if (_target === 'cancel') {
        linkUrl = '/';
    }
    $c.win.setPageFrameSrc($c.win.getFrame(), (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(linkUrl));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.applyJoin
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.applyJoin = async function () {
    /* sdd-asis-lifecycle:begin fn_ApplyJoin — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.benfcertForm || { elements: [] });
    if ($c.cm.fn_NullChk($c.util.getComponent('slc_benfcertApctTpCd'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_corpRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length != 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        $c.util.getComponent("ipt_corpRegNo").focus();
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_corpRegNo')))) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length != 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!($c.cm.fn_IsNumber($c.util.getComponent('ipt_bzRegNo')))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "회사영문명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpEngNm'))) {
        return;
    }
    $c.util.getComponent('dma_ApplyJoinReq').set('method', 'registerBenfcertApct');
    frm.action = '/outer/benfcertApct.do';
    { const nr = await scwin.tx_fn_ApplyJoin(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/message/message.xml", { "method": 'registerBenfcertApct' }); } };
    /* sdd-asis-lifecycle:end */
};
